package org.eclipse.rdf4j.workbench.commands;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.stream.Stream;

import org.eclipse.rdf4j.repository.config.RepositoryConfig;
import org.junit.jupiter.api.parallel.ResourceLock;
import org.junit.jupiter.api.parallel.Resources;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

/** Verifies that failing legacy-configuration test setup cannot contaminate subsequent tests. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class CreateServletTestIsolationTest {

	private static final String LEGACY_CONFIG = "org.eclipse.rdf4j.model.vocabulary.useLegacyConfig";

	@ParameterizedTest
	@MethodSource("legacyConfigurationCases")
	void legacyConfigurationTestRestoresPreviousProperty(String previous, boolean fail) throws Exception {
		String original = System.getProperty(LEGACY_CONFIG);
		CreateServlet originalServlet = CreateServletTest.servlet;
		CreateServlet failingServlet = mock(CreateServlet.class);
		AssertionError failure = new AssertionError("injected configuration failure");
		if (fail) {
			when(failingServlet.updateRepositoryConfig(anyString())).thenThrow(failure);
		} else {
			when(failingServlet.updateRepositoryConfig(anyString()))
					.thenReturn(new RepositoryConfig("legacy", "Legacy Test Repository"));
		}
		try {
			restoreProperty(previous);
			CreateServletTest.servlet = failingServlet;
			if (fail) {
				assertThatThrownBy(() -> new CreateServletTest().testUpdateRepositoryConfig_useLegacy_legacyConfig())
						.isSameAs(failure);
			} else {
				new CreateServletTest().testUpdateRepositoryConfig_useLegacy_legacyConfig();
			}
			assertThat(System.getProperty(LEGACY_CONFIG)).isEqualTo(previous);
		} finally {
			CreateServletTest.servlet = originalServlet;
			restoreProperty(original);
		}
	}

	private static Stream<Arguments> legacyConfigurationCases() {
		return Stream.of(null, "", "false", "true")
				.flatMap(previous -> Stream.of(Arguments.of(previous, false), Arguments.of(previous, true)));
	}

	private static void restoreProperty(String value) {
		if (value == null) {
			System.clearProperty(LEGACY_CONFIG);
		} else {
			System.setProperty(LEGACY_CONFIG, value);
		}
	}
}
